```cpp
// VoltForge Generated Firmware
// Target Board: ESP32_S3
// Peripheral: BMP280 -> SERVO_SG90

#include <Wire.h>

const int SENSOR_PIN = 2;
const int ACTUATOR_PIN = 8;

void setup() {
  Serial.begin(115200);
  pinMode(SENSOR_PIN, INPUT);
  pinMode(ACTUATOR_PIN, OUTPUT);
  digitalWrite(ACTUATOR_PIN, LOW);
  Serial.println(F("[SYSTEM] ESP32_S3 initialization complete."));
}

void loop() {
  int sensorValue = digitalRead(SENSOR_PIN);
  if (sensorValue == HIGH) {
    digitalWrite(ACTUATOR_PIN, HIGH);
    Serial.println(F("[ALERT] Sensor trigger detected -> Actuator ON"));
  } else {
    digitalWrite(ACTUATOR_PIN, LOW);
  }
  delay(100);
}
```

**Key Safety Points:**
1. Ensure common ground between all 5V/3.3V modules.
2. Add a flyback diode if SERVO_SG90 is an inductive relay or motor.
3. Pull-up resistor recommended on the BMP280 data line.

